#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../rotary-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=262144,repeat=argc>1?atoi(argv[1]):100;std::vector<float>x1(n),x2(n),c(n),s(n),expected(2*n),got(2*n);for(int i=0;i<n;i++){x1[i]=float((i*13+7)%257-128)/128.f;x2[i]=float((i*37+11)%257-128)/128.f;float angle=float(i/64)/powf(10000.f,2.f*float(i%64)/128.f);c[i]=cosf(angle);s[i]=sinf(angle);expected[i]=x1[i]*c[i]-x2[i]*s[i];expected[n+i]=x1[i]*s[i]+x2[i]*c[i];}float *a,*b,*dc,*ds,*o1,*o2;for(auto p:{&a,&b,&dc,&ds,&o1,&o2})CK(cudaMalloc(p,n*4));CK(cudaMemcpy(a,x1.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(b,x2.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dc,c.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(ds,s.data(),n*4,cudaMemcpyHostToDevice));Array<char*,6>data;data[0]=(char*)o1;data[1]=(char*)o2;data[2]=(char*)a;data[3]=(char*)b;data[4]=(char*)dc;data[5]=(char*)ds;auto ic=TrivialOffsetCalculator<4>();auto oc=TrivialOffsetCalculator<2>();auto f=[] GPU_LAMBDA(float a,float b,float c,float s)->thrust::tuple<float,float>{return {a*c-b*s,a*s+b*c};};auto launch=[&](){encode<2>(n,f,data,ic,oc);};launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch();CK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;CK(cudaMemcpy(got.data(),o1,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(got.data()+n,o2,n*4,cudaMemcpyDeviceToHost));float ma=0,mr=0;bool ok=true;for(int i=0;i<2*n;i++){float e=fabsf(got[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(got[i])&&e<=1e-3f;}all&=ok;char file[100];sprintf(file,"rotary_trial%d.bin",trial);FILE*fp=fopen(file,"wb");fwrite(got.data(),4,2*n,fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"rotary_kernel_only_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",2*n,ma,mr,repeat,file,2*n);}for(auto p:{a,b,dc,ds,o1,o2})CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
